s=section(172,'Hydrogen bonding: vapour pressure, boiling and anomalous water','ہائیڈروجن بندش: بخاراتی دباؤ، ابال اور پانی کا غیر معمولی رویہ','هایدروجني تړون: د بخار فشار، اېشېدنه او د اوبو غیرعادي چلند')
add(s,'heat-reservoir',('The water on the surface of earth acts like giant heat reservoir to moderate daily temperature variations.','زمین کی سطح پر پانی ایک بڑے حرارتی ذخیرے کی طرح کام کرتا ہے تاکہ روزانہ درجۂ حرارت کے اتار چڑھاؤ کو معتدل رکھے۔','د ځمکې پر سطحه اوبه د تودوخې د یوې سترې زېرمې په څېر عمل کوي، څو د تودوخې ورځني بدلونونه معتدل کړي.'))
add(s,'vapour-heading',('iii. Low Vapour Pressure','iii. کم بخاراتی دباؤ','iii. د بخار ټیټ فشار'),kind='heading')
add(s,'vapour-pressure',('The hydrogen bonding in water makes it difficult for the water molecules to escape into vapours. Therefore, the rate of conversion of water molecules into vapours is very low, so the vapour pressure of water is low.','پانی میں ہائیڈروجن بندش پانی کے سالموں کے لیے بخارات میں نکلنا مشکل بناتی ہے۔ لہٰذا پانی کے سالموں کے بخارات میں بدلنے کی شرح بہت کم ہوتی ہے، اس لیے پانی کا بخاراتی دباؤ کم ہوتا ہے۔','په اوبو کې هایدروجني تړون د اوبو د مالیکولونو بخار ته وتل ستونزمنوي. له همدې امله بخار ته د اوبو د مالیکولونو د بدلېدو کچه ډېره ټیټه ده، نو د اوبو د بخار فشار ټیټ دی.'))
add(s,'vaporization-heading',('iv. High Heat of Vaporization','iv. زیادہ حرارتِ تبخیر','iv. د تبخیر لوړه تودوخه'),kind='heading')
add(s,'vaporization-definition',('Heat of vaporization is the heat required to change one gram of liquid to vapour at its boiling point.','حرارتِ تبخیر وہ حرارت ہے جو کسی مائع کے ایک گرام کو اس کے نقطۂ ابال پر بخار میں بدلنے کے لیے درکار ہوتی ہے۔','د تبخیر تودوخه هغه تودوخه ده چې د مایع د یوه ګرام د هغه په اېشېدو ټکي کې په بخار بدلولو لپاره پکار وي.'))
add(s,'vaporization-explanation',('High Heat of vaporization is the direct indication of the strong attraction between molecules in water. The strong attractive forces between the liquid molecules are due to hydrogen bonding. The hydrogen bonding in water molecules effectively gives the high heat of vaporization. As water is heated and energy is absorbed, hydrogen bonds are continually being broken until at 100°C, with the absorption of an additional 2.26 kJ/g, water separates into individual molecules, going into the gaseous state.','زیادہ حرارتِ تبخیر پانی کے سالموں کے درمیان مضبوط کشش کی براہِ راست علامت ہے۔ مائع کے سالموں کے درمیان مضبوط کششی قوتیں ہائیڈروجن بندش کی وجہ سے ہوتی ہیں۔ پانی کے سالموں میں ہائیڈروجن بندش مؤثر طور پر زیادہ حرارتِ تبخیر پیدا کرتی ہے۔ جب پانی گرم کیا جاتا ہے اور توانائی جذب ہوتی ہے تو ہائیڈروجن بند مسلسل ٹوٹتے رہتے ہیں، یہاں تک کہ 100°C پر مزید 2.26 kJ/g جذب ہونے سے پانی الگ الگ سالموں میں جدا ہو کر گیس کی حالت میں چلا جاتا ہے۔','د تبخیر لوړه تودوخه د اوبو د مالیکولونو ترمنځ د قوي جذب مستقیمه نښه ده. د مایع د مالیکولونو ترمنځ قوي جذبي ځواکونه د هایدروجني تړون له امله دي. د اوبو په مالیکولونو کې هایدروجني تړون په اغېزمن ډول د تبخیر لوړه تودوخه رامنځته کوي. کله چې اوبه تودېږي او انرژي جذبوي، هایدروجني تړونونه پرله‌پسې ماتېږي، تر دې چې په 100°C کې د اضافي 2.26 kJ/g په جذبولو اوبه په جلا مالیکولونو وېشل کېږي او ګازي حالت ته ځي.'))
add(s,'boiling-heading',('v. High Boiling Point','v. زیادہ نقطۂ ابال','v. د اېشېدو لوړ ټکی'),kind='heading')
add(s,'boiling-hydrogen',('In water, there occurs stronger hydrogen bonding, so the vapour pressure of water is low. Water has high boiling point due to hydrogen bonding. Thus, the boiling point of water is 100°C at 1atm (760mm Hg).','پانی میں زیادہ مضبوط ہائیڈروجن بندش ہوتی ہے، اس لیے پانی کا بخاراتی دباؤ کم ہوتا ہے۔ ہائیڈروجن بندش کی وجہ سے پانی کا نقطۂ ابال زیادہ ہے۔ چنانچہ 1atm (760mm Hg) پر پانی کا نقطۂ ابال 100°C ہے۔','په اوبو کې لا قوي هایدروجني تړون شته، نو د اوبو د بخار فشار ټیټ دی. د هایدروجني تړون له امله اوبه د اېشېدو لوړ ټکی لري. په دې توګه په 1atm (760mm Hg) کې د اوبو د اېشېدو ټکی 100°C دی.'))
add(s,'boiling-comparison',('It is clear from table 5.4, that boiling point is determined by the strength of hydrogen bonding. For example, methane (CH₄) and diethyl ether (C₂H₅OC₂H₅), has low boiling points due to weak intermolecular forces.','جدول 5.4 سے واضح ہے کہ نقطۂ ابال ہائیڈروجن بندش کی مضبوطی سے متعین ہوتا ہے۔ مثلاً میتھین (CH₄) اور ڈائی ایتھائل ایتھر (C₂H₅OC₂H₅) کے نقاطِ ابال کمزور بین السالماتی قوتوں کی وجہ سے کم ہیں۔','له 5.4 جدول څخه څرګندېږي چې د اېشېدو ټکی د هایدروجني تړون د ځواک له مخې ټاکل کېږي. د بېلګې په توګه، میتان (CH₄) او ډای ایتیل ایتر (C₂H₅OC₂H₅) د کمزورو بین المالیکولي ځواکونو له امله د اېشېدو ټیټ ټکي لري.'))
add(s,'ethanol-water',('Both ethanol (C₂H₅OH) and water have strong hydrogen bonding, which accounts for their high boiling points.','ایتھانول (C₂H₅OH) اور پانی دونوں میں مضبوط ہائیڈروجن بندش ہوتی ہے، جو ان کے زیادہ نقاطِ ابال کا سبب بنتی ہے۔','ایتانول (C₂H₅OH) او اوبه دواړه قوي هایدروجني تړون لري، چې د دوی د اېشېدو د لوړو ټکو لامل دی.'))
add(s,'anomalous-heading',('vi. Anomalous Behaviour of Water','vi. پانی کا غیر معمولی رویہ','vi. د اوبو غیرعادي چلند'),kind='heading')
add(s,'anomalous-start',('The maximum density of water is 1.000 g/cm³ at 4°C. Water has the unusual property of contracting in volume as it is cooled to 4°C and then expanding when cooled from 4°C to 0°C. Therefore, 1 g of water occupies a volume greater than 1 cm³ at all temperatures except 4°C. Although, most liquids','4°C پر پانی کی زیادہ سے زیادہ کثافت 1.000 g/cm³ ہے۔ پانی کی غیر معمولی خاصیت یہ ہے کہ اسے 4°C تک ٹھنڈا کرنے پر اس کا حجم سکڑتا ہے اور پھر 4°C سے 0°C تک ٹھنڈا کرنے پر پھیلتا ہے۔ لہٰذا پانی کا 1 g، 4°C کے علاوہ تمام درجۂ حرارت پر 1 cm³ سے زیادہ حجم گھیرتا ہے۔ اگرچہ بیشتر مائعات','په 4°C کې د اوبو تر ټولو لوړ کثافت 1.000 g/cm³ دی. اوبه دا غیرعادي ځانګړنه لري چې تر 4°C پورې په سړېدو یې حجم راټولېږي او بیا له 4°C څخه تر 0°C پورې په سړېدو پراخېږي. له همدې امله 1 g اوبه، له 4°C پرته، په ټولو تودوخو کې له 1 cm³ څخه زیات حجم نیسي. که څه هم ډېری مایعات'),continuesOnPdfPage=173)
